<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { api } from './api';
const data=ref<any>(), selected=ref(0), running=ref(false);const phase=computed(()=>data.value?.phases?.[selected.value]);
onMounted(async()=>data.value=await api('/attack/scenario'));
function play(){running.value=!running.value;if(running.value){const timer=setInterval(()=>{selected.value=(selected.value+1)%data.value.phases.length;if(selected.value===data.value.phases.length-1){running.value=false;clearInterval(timer)}},900)}}
</script>
<template><section class="experience attack-experience" v-if="data"><div class="experience-heading compact"><div><span class="eyebrow">ATTACK MAP / 教学推演</span><h1>从告警开始，<br>让判断有迹可循</h1><p>{{data.description}}</p></div><div class="scenario-stamp"><span>当前推演</span><b>01</b><small>脱敏教学事件</small></div></div><div class="attack-dashboard"><section class="attack-stage"><div class="stage-head"><div><span class="eyebrow">事件链</span><b>{{phase.title}}</b></div><button @click="play">{{running?'暂停推演':'播放推演'}}</button></div><div class="stage-visual"><div class="signal signal-a"></div><div class="signal signal-b"></div><div class="signal signal-c"></div><div class="trace"><i v-for="(item,index) in data.phases" :key="item.id" :class="{active:index===selected,passed:index<selected}" @click="selected=index"><span>{{String(index+1).padStart(2,'0')}}</span><b>{{item.mitre}}</b></i></div><div class="stage-caption"><span>当前阶段</span><b>{{phase.time}} · {{phase.title}}</b><p>{{phase.detail}}</p></div></div></section><aside class="event-rail"><header><span class="eyebrow">处置时间线</span><small>点击节点查看</small></header><button v-for="(item,index) in data.phases" :key="item.id" class="event-row" :class="{active:index===selected}" @click="selected=index"><time>{{item.time}}</time><div><b>{{item.title}}</b><p>{{item.detail}}</p></div><i>{{item.mitre}}</i></button></aside></div><section class="control-strip"><div><span class="eyebrow">防护控制</span><h2>推演不等于实操</h2><p>所有内容由本地后端提供，是脱敏的教学状态；页面不会向目标系统发起请求。</p></div><article v-for="control in data.controls" :key="control.name"><i>✓</i><span>{{control.name}}</span><b>{{control.status}}</b><p>{{control.description}}</p></article></section></section><section v-else class="experience loading">正在读取教学推演…</section></template>
